mapper.select:
SELECT r.id, r.resource_id, r.user_id, u.nickname, r.score, r.content, r.status, r.like_count, r.created_at, r.updated_at, CASE WHEN #{viewerId} IS NULL THEN 0 WHEN EXISTS ( SELECT 1 FROM cms_review_like l WHERE l.review_id = r.id AND l.user_id = #{viewerId} ) THEN 1 ELSE 0 END AS liked_by_me, CASE WHEN #{viewerId} IS NULL THEN 0 WHEN r.user_id = #{viewerId} THEN 1 ELSE 0 END AS mine FROM cms_resource_review r INNER JOIN sys_user u ON u.id = r.user_id WHERE r.resource_id = #{resourceId}
AND r.status = 1
ORDER BY CASE WHEN r.status = 1 THEN 0 ELSE 1 END, r.like_count DESC, r.created_at DESC, r.id DESC

mapper.update:
UPDATE cms_resource_review
SET score = #{score},
    content = #{content},
    updated_at = #{now}
WHERE id = #{id}

UPDATE cms_resource_review
SET like_count = like_count + 1
WHERE id = #{id}

UPDATE cms_resource_review
SET like_count = GREATEST(like_count - 1, 0)
WHERE id = #{id}

mapper.delete:
DELETE FROM cms_resource_review
WHERE resource_id = #{resourceId}
  AND user_id = #{userId}
